import app from 'flarum/forum/app';
import Link from 'flarum/common/components/Link';
/** A member's avatar and name, linked to their profile, from the book's own payload. */
export default function person(p) {
  if (!p) return m("span", {
    className: "Longshot-person"
  }, app.translator.trans('core.lib.username.deleted_text'));
  const initial = (p.displayName || p.username || '?').charAt(0).toUpperCase();
  return m(Link, {
    className: "Longshot-person",
    href: app.route('user', {
      username: p.slug
    })
  }, p.avatarUrl ? m("img", {
    className: "Avatar",
    src: p.avatarUrl,
    alt: "",
    loading: "lazy",
    decoding: "async"
  }) : m("span", {
    className: "Avatar",
    "aria-hidden": "true"
  }, initial), m("span", {
    className: "username"
  }, p.displayName));
}
flarum.reg.add('ernestdefoe-longshot', 'forum/components/Avatar', person);